import React, { Component } from 'react';
import { Card, Button, Spin, Alert, Select, Form, Input, DatePicker, message, Icon, Breadcrumb } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';
import moment from 'moment';

const { Option } = Select;
const { TextArea } = Input;

class EditProgram extends Component {
    constructor(props) {
        super(props);
        this.state = {
            thematicAreas: [],
            program: null,
            loading: false,
            saving: false,
            error: null,
            selectedThematicArea: null,
            programName: '',
            programCode: '',
            programDescription: '',
            programOpeningDate: null,
            originalProgram: null
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        const programId = this.props.params.programId;
        if (programId) {
            this.fetchProgramData(programId);
            this.fetchThematicAreas();
        }
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchProgramData = async (programId) => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            // Fetch the program (organization unit level 3)
            const programData = await api.get(`organisationUnits/${programId}`, {
                fields: 'id,displayName,code,description,openingDate,parent[id,displayName,parent[id,displayName]]'
            });

            if (this._isMounted) {
                this.setState({
                    program: programData,
                    originalProgram: { ...programData },
                    selectedThematicArea: programData.parent.id || null,
                    programName: programData.displayName || '',
                    programCode: programData.code || '',
                    programDescription: programData.description || '',
                    programOpeningDate: programData.openingDate ? moment(programData.openingDate) : null,
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching program data:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch program data. Please try again.',
                    loading: false
                });
            }
        }
    };

    fetchThematicAreas = async () => {
        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                level: 2,
                paging: false,
                fields: 'id,displayName,code'
            });

            if (this._isMounted) {
                this.setState({
                    thematicAreas: data.organisationUnits || []
                });
            }
        } catch (error) {
            console.error('Error fetching thematic areas:', error);
        }
    };

    handleThematicAreaChange = (value) => {
        this.setState({ selectedThematicArea: value });
    };

    handleInputChange = (field, value) => {
        this.setState({ [field]: value });
    };

    handleCancel = () => {
        window.history.back();
    };

    handleSubmit = async () => {
        const { program, selectedThematicArea, programName, programCode, programDescription, programOpeningDate } = this.state;

        if (!selectedThematicArea) {
            message.error('Please select a thematic area');
            return;
        }

        if (!programName.trim()) {
            message.error('Please enter a program name');
            return;
        }

        this.setState({ saving: true });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            // Prepare the updated organization unit data
            const updatedOrgUnit = {
                id: program.id,
                name: programName,
                displayName: programName,
                shortName: programName.substring(0, 50), // DHIS2 shortName limit
                code: programCode || undefined,
                description: programDescription || undefined,
                openingDate: programOpeningDate ? programOpeningDate.format('YYYY-MM-DD') : undefined,
                parent: {
                    id: selectedThematicArea
                }
            };

            // Update the organization unit
            await api.update(`organisationUnits/${program.id}`, updatedOrgUnit);

            message.success('Program updated successfully!');

            // Navigate back to programs list
            const redirectUrl = `/sims-web-maintenance/#/list/organisationUnitSection/programsHierarchy`;
            window.location.href = redirectUrl;

        } catch (error) {
            console.error('Error updating program:', error);
            this.setState({ saving: false });

            let errorMessage = 'Failed to update program. Please try again.';
            if (error.response && error.response.data && error.response.data.message) {
                errorMessage = error.response.data.message;
            }

            message.error(errorMessage);
        }
    };

    hasChanges = () => {
        const { originalProgram, selectedThematicArea, programName, programCode, programDescription, programOpeningDate } = this.state;

        if (!originalProgram) return false;

        // Compare opening dates (handle both moment objects and strings)
        const originalOpeningDate = originalProgram.openingDate ? moment(originalProgram.openingDate).format('YYYY-MM-DD') : null;
        const currentOpeningDate = programOpeningDate ? programOpeningDate.format('YYYY-MM-DD') : null;

        return (
            originalProgram.displayName !== programName ||
            originalProgram.code !== programCode ||
            originalProgram.description !== programDescription ||
            originalProgram.parent.id !== selectedThematicArea ||
            originalOpeningDate !== currentOpeningDate
        );
    };

    render() {
        const {
            thematicAreas,
            program,
            loading,
            saving,
            error,
            selectedThematicArea,
            programName,
            programCode,
            programDescription,
            programOpeningDate
        } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '800px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
            borderBottom: '1px solid #f0f0f0'
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading program data...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={() => this.fetchProgramData(this.props.params.programId)}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        if (!program) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px', textAlign: 'center' }}>
                        <Icon type="warning" style={{ fontSize: '48px', color: '#faad14', marginBottom: '16px' }} />
                        <div style={{ fontSize: '16px', color: '#666' }}>Program not found</div>
                        <Button type="primary" onClick={this.handleCancel} style={{ marginTop: '16px' }}>
                            Go Back
                        </Button>
                    </div>
                </Card>
            );
        }

        const selectedThematicAreaName = thematicAreas.find(area => area.id === selectedThematicArea).displayName;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ marginBottom: '16px' }}>
                            <Breadcrumb>
                                <Breadcrumb.Item>
                                    <a href="/sims-web-maintenance/#/list/organisationUnitSection/programsHierarchy">Programs</a>
                                </Breadcrumb.Item>
                                <Breadcrumb.Item>Edit Program</Breadcrumb.Item>
                            </Breadcrumb>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Edit Program
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Update program details and organizational placement
                                </p>
                            </div>
                            <Button
                                icon="arrow-left"
                                onClick={this.handleCancel}
                                size="large"
                            >
                                Back
                            </Button>
                        </div>
                    </div>

                    {/* Form Content */}
                    <div style={{ padding: '32px' }}>
                        <div style={{ marginBottom: '24px', padding: '16px', backgroundColor: '#f9f9f9', borderRadius: '6px' }}>
                            <div style={{ fontSize: '14px', color: '#666', marginBottom: '8px' }}>Current Location:</div>
                            <div style={{ display: 'flex', alignItems: 'center' }}>
                                <Icon type="folder" style={{ color: '#1890ff', marginRight: '8px' }} />
                                <span style={{ fontWeight: '500' }}>
                                    {program.parent.parent.displayName} → {program.parent.displayName} → {program.displayName}
                                </span>
                            </div>
                        </div>

                        <Form layout="vertical">
                            <Form.Item
                                label="Select Thematic Area"
                                required
                                help="Choose which thematic area this program should belong to"
                            >
                                <Select
                                    placeholder="Select a thematic area"
                                    value={selectedThematicArea}
                                    onChange={this.handleThematicAreaChange}
                                    size="large"
                                    showSearch
                                    filterOption={(input, option) =>
                                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                                    }
                                >
                                    {thematicAreas.map(area => (
                                        <Option key={area.id} value={area.id}>
                                            <Icon type="folder" style={{ marginRight: '8px', color: '#1890ff' }} />
                                            {area.displayName}
                                        </Option>
                                    ))}
                                </Select>
                                {selectedThematicAreaName && selectedThematicArea !== program.parent.id && (
                                    <div style={{ marginTop: '8px', padding: '8px', backgroundColor: '#fff7e6', border: '1px solid #ffd591', borderRadius: '4px' }}>
                                        <Icon type="warning" style={{ color: '#fa8c16', marginRight: '8px' }} />
                                        <span style={{ color: '#fa8c16', fontSize: '12px' }}>
                                            This will move the program to "{selectedThematicAreaName}"
                                        </span>
                                    </div>
                                )}
                            </Form.Item>

                            <Form.Item
                                label="Program Name"
                                required
                            >
                                <Input
                                    placeholder="Enter program name"
                                    value={programName}
                                    onChange={(e) => this.handleInputChange('programName', e.target.value)}
                                    size="large"
                                />
                            </Form.Item>

                            <Form.Item
                                label="Program Code"
                                help="Optional unique identifier for the program"
                            >
                                <Input
                                    placeholder="Enter program code (optional)"
                                    value={programCode}
                                    onChange={(e) => this.handleInputChange('programCode', e.target.value)}
                                    size="large"
                                />
                            </Form.Item>

                            <Form.Item
                                label="Opening Date"
                                help="The date when this program was established"
                            >
                                <DatePicker
                                    placeholder="Select opening date"
                                    value={programOpeningDate}
                                    onChange={(date) => this.handleInputChange('programOpeningDate', date)}
                                    size="large"
                                    style={{ width: '100%' }}
                                    format="YYYY-MM-DD"
                                />
                            </Form.Item>

                            <Form.Item
                                label="Description"
                                help="Optional description for the program"
                            >
                                <TextArea
                                    placeholder="Enter program description (optional)"
                                    value={programDescription}
                                    onChange={(e) => this.handleInputChange('programDescription', e.target.value)}
                                    rows={4}
                                />
                            </Form.Item>

                            <Form.Item style={{ marginTop: '32px' }}>
                                <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                                    <Button
                                        size="large"
                                        onClick={this.handleCancel}
                                        disabled={saving}
                                    >
                                        Cancel
                                    </Button>
                                    <Button
                                        type="primary"
                                        size="large"
                                        onClick={this.handleSubmit}
                                        loading={saving}
                                        disabled={!selectedThematicArea || !programName.trim() || !this.hasChanges()}
                                    >
                                        <Icon type="save" />
                                        {this.hasChanges() ? 'Save Changes' : 'No Changes'}
                                    </Button>
                                </div>
                            </Form.Item>
                        </Form>
                    </div>
                </Card>
            </div>
        );
    }
}

EditProgram.contextTypes = {
    d2: PropTypes.object
};

export default EditProgram;



